mapper.select:
SELECT
    symbol,
    (bucket_start AT TIME ZONE 'Asia/Seoul') AS bucketStart,
    "open" AS open, high, low, "close" AS close, volume
FROM stocks.stock_data
WHERE symbol = #{req.symbol}
 AND bucket_start >= #{req.from} 
   AND bucket_start <  #{req.to} 
    ORDER BY bucket_start
 LIMIT #{req.limit}
